CREATE TABLE `erp_cleanup_backup` (
	`key` text PRIMARY KEY NOT NULL,
	`value` text NOT NULL,
	`revision` integer NOT NULL
);

--> statement-breakpoint
INSERT OR IGNORE INTO erp_cleanup_backup (key,value,revision) SELECT key,value,revision FROM erp_collections;
