UPDATE erp_collections SET value=(SELECT json_group_array(json(json_set(json_set(json_set(item.value,'$.projectManagerId',CASE WHEN EXISTS(SELECT 1 FROM json_each((SELECT value FROM erp_collections WHERE key='employees')) employee WHERE json_extract(employee.value,'$.id')=json_extract(item.value,'$.projectManagerId') AND json_extract(employee.value,'$.role')='Project Manager') THEN json_extract(item.value,'$.projectManagerId') ELSE '' END,'$.projectManagerName',CASE WHEN EXISTS(SELECT 1 FROM json_each((SELECT value FROM erp_collections WHERE key='employees')) employee WHERE json_extract(employee.value,'$.id')=json_extract(item.value,'$.projectManagerId') AND json_extract(employee.value,'$.role')='Project Manager') THEN (SELECT json_extract(employee.value,'$.name') FROM json_each((SELECT value FROM erp_collections WHERE key='employees')) employee WHERE json_extract(employee.value,'$.id')=json_extract(item.value,'$.projectManagerId')) ELSE 'Unassigned' END),'$.siteEngineerId',CASE WHEN EXISTS(SELECT 1 FROM json_each((SELECT value FROM erp_collections WHERE key='employees')) employee WHERE json_extract(employee.value,'$.id')=json_extract(item.value,'$.siteEngineerId') AND json_extract(employee.value,'$.role')='Site Engineer') THEN json_extract(item.value,'$.siteEngineerId') ELSE '' END,'$.siteEngineerName',CASE WHEN EXISTS(SELECT 1 FROM json_each((SELECT value FROM erp_collections WHERE key='employees')) employee WHERE json_extract(employee.value,'$.id')=json_extract(item.value,'$.siteEngineerId') AND json_extract(employee.value,'$.role')='Site Engineer') THEN (SELECT json_extract(employee.value,'$.name') FROM json_each((SELECT value FROM erp_collections WHERE key='employees')) employee WHERE json_extract(employee.value,'$.id')=json_extract(item.value,'$.siteEngineerId')) ELSE 'Unassigned' END),'$.designerId',CASE WHEN EXISTS(SELECT 1 FROM json_each((SELECT value FROM erp_collections WHERE key='employees')) employee WHERE json_extract(employee.value,'$.id')=json_extract(item.value,'$.designerId') AND json_extract(employee.value,'$.role')='Designer') THEN json_extract(item.value,'$.designerId') ELSE '' END,'$.designerName',CASE WHEN EXISTS(SELECT 1 FROM json_each((SELECT value FROM erp_collections WHERE key='employees')) employee WHERE json_extract(employee.value,'$.id')=json_extract(item.value,'$.designerId') AND json_extract(employee.value,'$.role')='Designer') THEN (SELECT json_extract(employee.value,'$.name') FROM json_each((SELECT value FROM erp_collections WHERE key='employees')) employee WHERE json_extract(employee.value,'$.id')=json_extract(item.value,'$.designerId')) ELSE 'Unassigned' END))) FROM json_each(erp_collections.value) item),revision=revision+1 WHERE key='projects';
