UPDATE erp_collections SET value=(SELECT json_group_array(json(CASE WHEN json_extract(item.value,'$.type')='project_assigned' THEN json_set(json_remove(item.value,'$.emailNotification'),'$.message','Project saved. Review the assigned team in Projects & Clients.') ELSE item.value END)) FROM json_each(erp_collections.value) item),revision=revision+1 WHERE key='notifications';
--> statement-breakpoint
UPDATE erp_collections SET value=(SELECT json_group_array(json(json_set(employee.value,'$.assignedProjectIds',json((SELECT json_group_array(assignment.value) FROM json_each(employee.value,'$.assignedProjectIds') assignment WHERE EXISTS(SELECT 1 FROM json_each((SELECT value FROM erp_collections WHERE key='projects')) project WHERE json_extract(project.value,'$.id')=assignment.value)))))) FROM json_each(erp_collections.value) employee),revision=revision+1 WHERE key='employees';
--> statement-breakpoint
UPDATE erp_collections SET value=(SELECT json_group_array(json(json_set(task.value,'$.assignedUserId',COALESCE((SELECT json_extract(employee.value,'$.id') FROM json_each((SELECT value FROM erp_collections WHERE key='employees')) employee WHERE json_extract(employee.value,'$.id')=json_extract(task.value,'$.assignedUserId') OR json_extract(employee.value,'$.name')=json_extract(task.value,'$.assignedUserName') LIMIT 1),''),'$.assignedUserName',COALESCE((SELECT json_extract(employee.value,'$.name') FROM json_each((SELECT value FROM erp_collections WHERE key='employees')) employee WHERE json_extract(employee.value,'$.id')=json_extract(task.value,'$.assignedUserId') OR json_extract(employee.value,'$.name')=json_extract(task.value,'$.assignedUserName') LIMIT 1),'Unassigned')))) FROM json_each(erp_collections.value) task),revision=revision+1 WHERE key='tasks';
